DIRS=L('meta-appeal-links-and-forms-directory','Meta appeal links directory')
SEND='<h2 id="what-to-send-us">What to send us</h2><p>Message us on <a href="https://wa.me/19342012490">WhatsApp</a> or email <a href="mailto:team@unbanz.com">team@unbanz.com</a> with:</p><ul><li>The username or profile link.</li><li>A screenshot of the exact notice, with the date.</li><li>What you already tried (appeal, ID upload, verification).</li><li>Never your password or login codes.</li></ul>'

AQ=('Business Support Home (Account Quality)','https://business.facebook.com/accountquality','Shows restrictions on personal advertising access, Pages, ad accounts and Business Portfolios, with Request review where it is offered.')
AC=('Accounts Center','https://accountscenter.facebook.com/','Password, two-factor, devices, linked Instagram and Facebook profiles, and some identity checks.')
MV=('Meta Verified','https://www.facebook.com/meta-verified','Paid subscription with a badge and support chat for eligible personal profiles. It does not override a disabled-account decision.')
BILL=('Ad account billing and payments','https://www.facebook.com/business/help/953826331734492','How Meta handles billing, open balances and payment methods on ad accounts.')
PX=('About the Meta Pixel','https://www.facebook.com/business/help/742478679120153','How pixels are shared across Business Portfolios and ad accounts.')

PAGES=[
mk('accounts-center-says-restricted-but-facebook-looks-normal','Accounts Center Says Restricted but Facebook Looks Normal','Accounts Center restricted, Facebook looks fine',
 'Accounts Center shows a restriction, but Facebook still opens and looks normal. How to tell which asset is hit and which review to use.',
 'Accounts Center says restricted, but Facebook looks normal.','A restriction can sit on one asset while your feed still loads. Name the layer before you appeal.',
 '<strong>If Accounts Center or Account Quality shows a restriction while Facebook still looks normal, you are usually restricted on advertising access, a Page, an ad account or a linked Instagram feature, not locked out of login.</strong> Open Business Support Home on a computer, screenshot the exact asset named, and request a review only for that asset. Do not create a second profile. Meta makes the final decision.',
 [('Name the asset','Profile ads, Page, ad account or Instagram.'),('Login still works','This is not a disabled profile.'),('One review','Request review on the asset that is listed.')],
 '<h2 id="why-it-looks-normal">Why Facebook can still look normal</h2><ul><li>Your personal feed, Messenger and friends list can work while personal advertising access is restricted.</li><li>A Page can be restricted from advertising or unpublished while your profile is fine.</li><li>An ad account or Business Portfolio can be down while you still open facebook.com.</li><li>Instagram linked through Accounts Center can show a separate Account Status issue.</li></ul><h2 id="steps">What to do</h2><ol><li>Open Accounts Center and note every warning.</li><li>On a computer, open Business Support Home and expand each listed asset.</li><li>Screenshot the reason line with the asset name visible.</li><li>If a Request review button is offered, use it once with a short factual note.</li><li>If login itself fails with a disabled notice, switch to '+L('guides/facebook-account-disabled-appeal','the Facebook disabled appeal guide')+' instead.</li></ol><p>Related: '+L('how-to-tell-profile-vs-ad-account-vs-page-restriction','profile vs ad account vs Page')+', '+L('facebook-page-restricted-from-advertising-business','Page restricted from advertising')+', '+DIRS+'.</p>',
 [('links','Official links',[AC,AQ,ADS[0],ADS[1],FB[4],META[0]])],
 [STEPS,SEND],
 DIRS+', '+L('meta-ad-account-restricted-vs-disabled','restricted vs disabled')+', '+L('how-to-contact-meta-about-a-disabled-account','how to contact Meta')+'.',
 [('Is my account disabled?','Not if you can still log in and use Facebook normally. A restriction on ads or a Page is a different layer.'),('Should I appeal from the login screen?','Only if you see a disabled or suspended notice at login. Otherwise use Business Support Home.'),('Does clearing the cache help?','It does not remove a Meta restriction. Check Account Quality on a computer.')]),

mk('facebook-disabled-while-meta-verified-is-active','Facebook Disabled While Meta Verified Is Active: What Still Works','Disabled with Meta Verified active',
 'Your Facebook profile was disabled or suspended while Meta Verified was still active. What the subscription can and cannot do, and which official appeal to use.',
 'Facebook disabled, but Meta Verified was active.','Meta Verified does not keep a disabled profile online. Use the disabled notice first.',
 '<strong>Meta Verified does not stop a Facebook profile from being disabled, and a paid badge does not replace the appeal on the disabled notice.</strong> Screenshot the notice, appeal once from that screen, and use any Meta Verified support chat only as a follow-up channel if it still opens. Do not create a replacement profile. Meta makes the final decision.',
 [('Notice first','The disabled screen is the real appeal.'),('Verified chat','Support, not an override.'),('No second profile','Wait for the decision.')],
 '<h2 id="what-verified-does">What Meta Verified does here</h2><ul><li>It can open a support chat for eligible subscribers about account problems.</li><li>It does not give a private “restore” link or a special appeal form.</li><li>If the profile is fully disabled, some Verified features stop until the profile is back.</li></ul><h2 id="steps">Steps</h2><ol><li>Screenshot the disabled or suspended message, including any countdown.</li><li>Use Disagree with decision or Request review on that screen once.</li><li>Complete any ID or video selfie step Meta shows.</li><li>If Meta Verified chat still opens from another working login or email receipt, ask about the open appeal and share the same facts, not a new story.</li><li>If a hack came first, also use facebook.com/hacked. See '+L('facebook-hacked-then-disabled-same-day','hacked then disabled same day')+'.</li></ol><p>More: '+L('guides/facebook-account-disabled-appeal','Facebook disabled appeal')+', '+L('facebook-appeal-links-and-forms-directory','Facebook appeal links')+', '+L('how-to-contact-meta-about-a-disabled-account','how to contact Meta')+'.</p>',
 [('links','Official links',[FB[0],FB[1],MV,META[0],META[1],AQ])],
 [STEPS,SEND],
 DIRS+', '+L('instagram-appeal-rejected-what-to-check-next','Instagram appeal rejected, what next')+', '+L('facebook-restriction-says-final-no-explanation','restriction says final')+'.',
 [('Does Meta Verified reopen a disabled account?','No. It may offer support chat. The disabled-account decision still runs through Meta’s own appeal.'),('Should I cancel Meta Verified?','Not required for the appeal. Focus on the notice first.'),('Can I appeal by email because I am verified?','No. Meta does not process account appeals by email.')]),

mk('meta-ad-account-disabled-with-open-balance','Meta Ad Account Disabled With an Open Balance: What to Do','Ad account disabled, open balance',
 'Your Meta ad account is disabled or restricted and still shows an open balance or unpaid amount. What to check in billing, when to request a review, and what not to do.',
 'Ad account disabled with an open balance.','Clear what billing Meta shows, then request a review once if it is offered. Do not open a new ad account to dodge it.',
 '<strong>A disabled Meta ad account can still show an open balance, failed charges or amount due.</strong> Open Business Support Home and billing on a computer as an admin, screenshot both, settle only what Meta’s own billing screen shows, then request a review once if offered. Opening a new ad account to avoid the restriction can be treated as circumventing systems. Meta makes the final decision.',
 [('Billing screen','Use Meta’s own amount due.'),('One review','After you fix what you can.'),('No new account','Do not dodge the restriction.')],
 '<h2 id="order">Order that usually makes sense</h2><ol><li>Confirm you are still an admin of the Business Portfolio and the ad account.</li><li>Open Business Support Home and read the exact reason on the ad account.</li><li>Open billing and payment methods. Note any open balance, failed payment or unpaid amount Meta lists.</li><li>Update an expired card or fix a declined method only inside Meta’s billing tools.</li><li>If Request review is offered, write a short note: what the business sells, what you changed, and that you want the ad account reviewed.</li><li>Keep ads and landing pages aligned with Advertising Standards before you ask.</li></ol><p>Related: '+L('guides/meta-ad-account-restricted','Meta ad account restricted')+', '+L('meta-ad-account-appeal-links-directory','ad account appeal links')+', '+L('guides/meta-ad-payment-declined-fix','payment declined')+', '+L('ad-account-disabled-after-chargeback-or-payment-dispute','after a chargeback')+'.</p>',
 [('links','Official links',[AQ,ADS[0],ADS[1],BILL,ADS[4],ADS[3]])],
 [STEPS,SEND],
 DIRS+', '+L('meta-ad-account-restricted-vs-disabled','restricted vs disabled')+', '+L('business-manager-disabled','Business Manager disabled')+'.',
 [('Will paying the balance restore the ad account by itself?','Not always. A policy restriction still needs its own review. Paying only settles the billing side.'),('Should I dispute the charge with my bank?','A chargeback can itself trigger or worsen ad account problems. Use Meta’s billing tools first.'),('Can I move spend to a new ad account?','Creating new ad accounts to avoid a restriction can make things worse.')]),

mk('facebook-page-restricted-but-ad-account-ok','Facebook Page Restricted but Ad Account OK: What It Means','Page restricted, ad account fine',
 'Your Facebook Page is restricted or unpublished while the ad account still looks fine. How the layers differ and which review to open.',
 'Page restricted, but the ad account looks fine.','These are separate assets. Fix and review the Page, not a healthy ad account.',
 '<strong>A Facebook Page can be restricted from advertising, unpublished or limited while the linked ad account still shows as active.</strong> Open Business Support Home, select the Page (not the ad account), read the reason, and request a review for the Page if offered. Ads that need that Page as the identity will still fail until the Page is cleared. Meta makes the final decision.',
 [('Different assets','Page vs ad account.'),('Review the Page','Do not waste the ad account review.'),('Ads need the Page','Delivery can still stop.')],
 '<h2 id="tell-apart">How to tell the layers apart</h2><ul><li><strong>Page restricted from advertising:</strong> the Page cannot be used as the ads identity. See '+L('facebook-page-restricted-from-advertising-business','Page restricted from advertising')+'.</li><li><strong>Page unpublished:</strong> the Page is hidden from the public. See '+L('facebook-page-unpublished-vs-account-disabled','Page unpublished vs account disabled')+' and '+L('facebook-business-page-unpublished-what-to-do','Page unpublished: what to do')+'.</li><li><strong>Ad account OK:</strong> billing and the ad account status look fine, but campaigns that require the restricted Page will not deliver normally.</li><li><strong>Personal profile:</strong> if your login is also limited, that is a third layer. See '+L('how-to-tell-profile-vs-ad-account-vs-page-restriction','profile vs ad account vs Page')+'.</li></ul><h2 id="steps">Steps</h2><ol><li>Screenshot Account Quality with the Page name and reason visible.</li><li>Confirm the ad account is not also listed as restricted.</li><li>Request a review on the Page only, once, with what you changed on the Page or its content.</li><li>Ask another Page admin to check if you lost admin access.</li><li>Do not create a replacement Page while a review is open.</li></ol><p>Directories: '+DIRS+', '+L('meta-ad-account-appeal-links-directory','ad account appeal links')+'.</p>',
 [('links','Official links',[AQ,ADS[0],ADS[1],ADS[3],FB[4]])],
 [STEPS,SEND],
 DIRS+', '+L('guides/facebook-page-restricted','Facebook Page restricted guide')+', '+L('facebook-disabled-page-admin-lost-pages','profile disabled, Pages lost')+'.',
 [('Why do ads stop if the ad account is fine?','Many ads need an eligible Page as the identity. A restricted Page blocks that even when the ad account itself is open.'),('Can I switch the ads to another Page?','Only if that Page is eligible and allowed for your business. Creating a copycat Page can lead to more restrictions.'),('Who can request the Page review?','A Page admin, from Business Support Home on a computer.')]),
]
